  /**
   * Method under test:
   * {@link DeviceInfoProtos.ProtoUpdateInfo#parseFrom(InputStream)}
   */
  @Test
  void testProtoUpdateInfoParseFrom6() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class, () -> DeviceInfoProtos.ProtoUpdateInfo.parseFrom(input));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

